urlset:
{%- set bookshelf_section = get_section(path="bookshelf/_index.md") %}
{%- set hide_bookshelf = bookshelf_section.extra.visible is not defined or not bookshelf_section.extra.visible %}
{%- for sitemap_entry in entries %}
{%- if sitemap_entry.extra.hidden is not defined or not sitemap_entry.extra.hidden %}
{%- if hide_bookshelf and "/bookshelf/" in sitemap_entry.permalink %}{% continue %}{% endif -%}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
